#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
const int MAX = 400010;
vector<long long> factorials(MAX);
vector<long long> invFactorials(MAX);

struct Triplet {
    long long gcd, x, y;
    Triplet(long long gcd, long long x, long long y) : gcd(gcd), x(x), y(y) {}
};

void initialize() {
    factorials[0] = 1;
    invFactorials[0] = 1;
    for (int i = 1; i < MAX; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
        invFactorials[i] = (invFactorials[i - 1] * modInverse(i, MOD)) % MOD;
    }
}

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    return (factorials[n] * invFactorials[r] % MOD) * invFactorials[n - r] % MOD;
}

long long binPow(long long base, long long exp) {
    long long result = 1;
    long long b = base % MOD;
    long long e = exp;
    while (e > 0) {
        if (e & 1) result = (result * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return result;
}

Triplet extendedEuclidean(long long a, long long b) {
    if (a == 0) return Triplet(b, 0, 1);
    Triplet res = extendedEuclidean(b % a, a);
    long long x = res.y - (b / a) * res.x;
    long long y = res.x;
    return Triplet(res.gcd, x, y);
}

long long modInverse(long long a, long long m) {
    Triplet res = extendedEuclidean(a, m);
    if (res.gcd != 1) return -1;
    return (res.x % m + m) % m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    initialize();

    int n;
    long long k;
    cin >> n >> k;

    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }
    if (n <= k) {
        cout << 0 << "\n";
        return 0;
    }

    long long answer = nCr(n, (int)k);
    int remainingCols = n - (int)k;
    long long total = 0;

    for (int i = 0; i <= remainingCols; i++) {
        long long tempVal = nCr(remainingCols, i);
        tempVal = (tempVal * binPow(remainingCols - i, n)) % MOD;
        if (i & 1) {
            total -= tempVal;
            if (total < 0) total += MOD;
        } else {
            total += tempVal;
            if (total >= MOD) total -= MOD;
        }
    }

    cout << (2 * ((answer * total) % MOD)) % MOD << "\n";

    return 0;
}

